const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('index.html','utf8');
class Element {
  constructor(dataset={}) { this.dataset=dataset;this.attrs={};this.listeners={};this.hidden=false;this.value='';this.textContent='';this.classes=new Set();this.classList={add:x=>this.classes.add(x),remove:x=>this.classes.delete(x),contains:x=>this.classes.has(x),toggle:(x,on)=>{if(on)this.classes.add(x);else this.classes.delete(x)}}; }
  setAttribute(k,v){this.attrs[k]=v} getAttribute(k){return this.attrs[k]}
  addEventListener(k,fn){this.listeners[k]=fn} click(){this.listeners.click?.({target:{closest:()=>true},clientX:100,clientY:100})}
  focus(){this.focused=true} showModal(){this.open=true} close(){this.open=false}
  getBoundingClientRect(){return {left:10,top:10,right:500,bottom:500}}
}
const singles={};
for(const key of ['.theme-toggle','meta[name=\"theme-color\"]','.menu-toggle','.navigation','.filter-status','#case-dialog','#case-title','#case-meta','#case-copy','.close-dialog','#subscribe-form','#subscribe-status','#email'])singles[key]=new Element();
const filters=['All','Design','Data','Freelancing','Field notes'].map(x=>new Element({filter:x}));
const posts=['Design','Field notes','Design','Data','Field notes','Freelancing'].map(x=>new Element({tag:x}));
const cases=['tidepool','ledger','delay','handbook'].map(x=>new Element({case:x}));
const navLinks=Array.from({length:4},()=>new Element());
singles['.navigation'].querySelectorAll=()=>navLinks;
const root=new Element();root.dataset.theme='light';
const document={documentElement:root,querySelector:x=>{if("'!singles[x])throw Error('"'Unknown selector '+x);return singles[x]},querySelectorAll:x=>({'.filter':filters,'.post':posts,'[data-case]':cases}[x]),addEventListener(){}};
const storage={};const context={document,matchMedia:()=>({matches:false,addEventListener(){}}),localStorage:{setItem:(k,v)=>storage[k]=v},window:{location:{href:''}},encodeURIComponent};
vm.createContext(context);
const scripts=[...html.matchAll(/<script>([\\s\\S]*?)<\\/script>/g)].map(x=>x[1]);
new vm.Script(scripts[1]);vm.runInContext(scripts[1],context);
const assert=(ok,msg)=>{if("'!ok)throw Error(msg)};
singles['"'.theme-toggle'].click();assert(root.dataset.theme==='dark','Theme switch');assert(storage['maya-theme']==='dark','Theme persistence');assert(singles['.theme-toggle'].attrs['aria-label']==='Switch to light color scheme','Theme accessible name');
singles['.theme-toggle'].click();assert(root.dataset.theme==='light','Theme return');
const expected=[6,2,1,1,2];filters.forEach((f,i)=>{f.click();assert(posts.filter(p=>"'!p.hidden).length===expected[i],'"'Filter '+f.dataset.filter);assert(filters.filter(x=>x.attrs['aria-pressed']==='true').length===1,'Only one active filter')});filters[0].click();
singles['.menu-toggle'].click();assert(singles['.navigation'].classes.has('open'),'Mobile menu opens');navLinks[0].click();assert("'!singles['"'.navigation'].classes.has('open'),'Menu closes after navigation');
cases.forEach(button=>{button.click();assert(singles['#case-dialog'].open,'Case opens');assert(singles['#case-title'].textContent.length>0,'Case has title');assert(singles['#case-copy'].innerHTML.includes('<p>'),'Case has text');singles['.close-dialog'].click();assert("'!singles['"'#case-dialog'].open,'Case closes')});
singles['#email'].value='reader@example.org';singles['#subscribe-form'].listeners.submit({preventDefault(){}});assert(context.window.location.href.startsWith('mailto:maya@lindqvist.example?subject='),'Subscription email prepared');assert(decodeURIComponent(context.window.location.href).includes('reader@example.org'),'Subscription includes email');
console.log('PASS: JavaScript syntax, light/dark switching, theme persistence, all five filters, mobile menu, all four case-study dialogs, subscription request.');
JS"

